437	// handleBatchUpdateWeight changes only the weights of several instances of
438	// one path-addressed service. The body is one JSON object with a non-empty
439	// updates list; every entry is validated and every target confirmed to exist
440	// before any write, so an invalid or incomplete batch changes no record and
441	// the store applies the whole batch atomically.
442	func (s *Server) handleBatchUpdateWeight(c *gin.Context) {
443		bag, apiErr := buildParamBag(c)
444		if apiErr != nil {
445			writeError(c, apiErr)
446			return
447		}
448		serviceName := strings.TrimSpace(c.Param("serviceName"))
449		if serviceName == "" {
