1	package api
2	
3	import (
4		"database/sql"
5		"fmt"
6		"net/http"
7		"path/filepath"
8		"strings"
9		"testing"
10		"time"
11	
12		"github.com/luwa07832/service-discovery-api/internal/store"
13	)
14	
15	// discoverEntries enumerates the four public single-service discovery
16	// entries the atomic lost cleanup must hold for.
17	var discoverEntries = []struct {
18		name   string
19		method string
20		target string
21		body   any
22	}{
23		{"get query entry", http.MethodGet,
24			"/api/v1/discover?service_name=svc&evaluate_at=" + at(10) + "&heartbeat_timeout=5m", nil},
25		{"get path entry", http.MethodGet,
26			"/api/v1/services/svc/discover?evaluate_at=" + at(10) + "&heartbeat_timeout=5m", nil},
27		{"post query entry", http.MethodPost, "/api/v1/discover", map[string]any{
28			"service_name": "svc", "evaluate_at": at(10), "heartbeat_timeout": "5m"}},
29		{"post path entry", http.MethodPost, "/api/v1/services/svc/discover", map[string]any{
30			"evaluate_at": at(10), "heartbeat_timeout": 300}},
31	}
32	
33	// seedAtomicFixture registers two strictly lost records (one of them
34	// unhealthy), two healthy fresh candidates, one unhealthy fresh record and
35	// one record of another service that is old enough to look lost but must
36	// never be touched by a svc-scoped discovery.
37	func seedAtomicFixture(t *testing.T, router http.Handler) {
38		t.Helper()
39		instances := []map[string]any{
40			{"service_name": "svc", "instance_id": "lost-a", "address": "10.0.0.1",
41				"port": 8001, "healthy": true, "weight": 10, "heartbeat_at": at(0)},
42			{"service_name": "svc", "instance_id": "lost-b", "address": "10.0.0.2",
43				"port": 8002, "healthy": false, "weight": 9, "heartbeat_at": at(1)},
44			{"service_name": "svc", "instance_id": "fresh-high", "address": "10.0.0.3",
45				"port": 8003, "healthy": true, "weight": 8, "heartbeat_at": at(9)},
46			{"service_name": "svc", "instance_id": "fresh-low", "address": "10.0.0.4",
47				"port": 8004, "healthy": true, "weight": 5, "heartbeat_at": at(9)},
48			{"service_name": "svc", "instance_id": "sick-fresh", "address": "10.0.0.5",
49				"port": 8005, "healthy": false, "weight": 7, "heartbeat_at": at(9)},
50			{"service_name": "other", "instance_id": "other-1", "address": "10.0.1.1",
51				"port": 9001, "healthy": true, "weight": 1, "heartbeat_at": at(0)},
52		}
53		for _, instance := range instances {
54			registerInstance(t, router, instance)
55		}
56	}
57	
58	// failDeleteOf installs a trigger that aborts the deletion of one specific
59	// instance. The lost records are deleted in registration order, so the
60	// deletion of lost-a is already executed when the deletion of lost-b fails.
61	// The returned function removes the trigger again.
62	func failDeleteOf(t *testing.T, dbPath, instanceID string) (clear func()) {
63		t.Helper()
64		db, err := sql.Open("sqlite", dbPath)
65		if err != nil {
66			t.Fatalf("open second connection: %v", err)
67		}
68		quoted := strings.ReplaceAll(instanceID, "'", "''")
69		statement := fmt.Sprintf(`
70	CREATE TRIGGER discover_test_fail_delete BEFORE DELETE ON service_instances
71	WHEN OLD.instance_id = '%s'
72	BEGIN SELECT RAISE(ABORT, 'simulated delete failure'); END`, quoted)
73		if _, err := db.Exec(statement); err != nil {
74			db.Close()
75			t.Fatalf("install trigger: %v", err)
76		}
77		return func() {
78			if _, err := db.Exec("DROP TRIGGER discover_test_fail_delete"); err != nil {
79				t.Fatalf("drop trigger: %v", err)
80			}
81			if err := db.Close(); err != nil {
82				t.Fatalf("close second connection: %v", err)
83			}
84		}
85	}
86	
87	// svcRecords reads the svc records through the public list entry and indexes
88	// them by instance id.
89	func svcRecords(t *testing.T, router http.Handler) map[string]map[string]any {
90		t.Helper()
91		rec := doRequest(t, router, http.MethodGet, "/api/v1/services/svc/instances", nil)
