309			rec := doRequest(t, router, http.MethodGet, target, nil)
310			expectParameterError(t, rec)
311			if out := decodeBody(t, rec); len(out) != 1 {
312				t.Fatalf("%s: error body must contain only the error object: %v", target, out)
313			}
314		}
315	
316		postBodies := []map[string]any{
317			{"service_name": "  ", "evaluate_at": at(10), "heartbeat_timeout": "5m"},
318			{"service_name": "svc", "heartbeat_timeout": "5m"},
319			{"service_name": "svc", "evaluate_at": "soon", "heartbeat_timeout": "5m"},
320			{"service_name": "svc", "evaluate_at": at(10)},
321			{"service_name": "svc", "evaluate_at": at(10), "heartbeat_timeout": 0},
322			{"service_name": "svc", "evaluate_at": at(10), "heartbeat_timeout": -30},
323			{"service_name": "svc", "evaluate_at": at(10), "heartbeat_timeout": "abc"},
324			{"service_name": "svc", "evaluate_at": at(8), "heartbeat_timeout": "5m"},
325		}
326		for _, body := range postBodies {
327			rec := doRequest(t, router, http.MethodPost, "/api/v1/services/svc/discover", body)
328			expectParameterError(t, rec)
329			if out := decodeBody(t, rec); len(out) != 1 {
330				t.Fatalf("%v: error body must contain only the error object: %v", body, out)
331			}
332		}
333	
334		// No rejected request deleted or altered anything, including the two
335		// strictly lost records that a valid request would have removed.
336		expectRecords(t, router, atomicFixtureRecords())
337		if other, err := st.ListInstances("other"); err != nil || len(other) != 1 {
338			t.Fatalf("other service changed: %v err=%v", other, err)
339		}
