342	// TestDiscoverTimeoutBoundaryAcrossEntries pins the strict lost boundary on
343	// every discovery entry: evaluate_at exactly heartbeat_at + timeout keeps
344	// the record online, one second later evicts and deletes it.
345	func TestDiscoverTimeoutBoundaryAcrossEntries(t *testing.T) {
346		// One second past the boundary: heartbeat 12:05 + 5m < 12:10:01.
347		past := time.Date(2026, 10, 1, 12, 10, 1, 0, time.UTC).Format(time.RFC3339)
348		pastEntries := []struct {
349			method string
350			target string
351			body   any
352		}{
353			{http.MethodGet, "/api/v1/discover?service_name=svc&evaluate_at=" + past + "&heartbeat_timeout=5m", nil},
354			{http.MethodGet, "/api/v1/services/svc/discover?evaluate_at=" + past + "&heartbeat_timeout=5m", nil},
355			{http.MethodPost, "/api/v1/discover", map[string]any{
356				"service_name": "svc", "evaluate_at": past, "heartbeat_timeout": "5m"}},
357			{http.MethodPost, "/api/v1/services/svc/discover", map[string]any{
358				"evaluate_at": past, "heartbeat_timeout": 300}},
359		}
360		for index, entry := range discoverEntries {
361			t.Run(entry.name, func(t *testing.T) {
362				router, st := testRouter(t)
363				registerInstance(t, router, map[string]any{
364					"service_name": "svc", "instance_id": "edge", "healthy": true,
365					"weight": 1, "heartbeat_at": at(5),
366				})
367	
368				// Exactly on the boundary: online, returned, kept.
369				rec := doRequest(t, router, entry.method, entry.target, entry.body)
370				if rec.Code != http.StatusOK {
371					t.Fatalf("boundary status = %d, body %s", rec.Code, rec.Body.String())
372				}
373				if ids := instanceIDs(t, decodeBody(t, rec)); len(ids) != 1 || ids[0] != "edge" {
374					t.Fatalf("boundary ids = %v, want [edge]", ids)
375				}
376				if _, found, _ := st.GetInstance("svc", "edge"); !found {
377					t.Fatalf("boundary record deleted")
378				}
379	
380				// Strictly past the boundary: lost, excluded, deleted.
381				pastEntry := pastEntries[index]
382				rec = doRequest(t, router, pastEntry.method, pastEntry.target, pastEntry.body)
383				if rec.Code != http.StatusOK {
384					t.Fatalf("past-boundary status = %d, body %s", rec.Code, rec.Body.String())
385				}
386				if ids := instanceIDs(t, decodeBody(t, rec)); len(ids) != 0 {
387					t.Fatalf("past-boundary ids = %v, want []", ids)
388				}
389				if _, found, _ := st.GetInstance("svc", "edge"); found {
390					t.Fatalf("strictly lost record not deleted")
391				}
392			})
393		}
394	}
