293			}
294		}
295	}
296	
297	// TestBatchHeartbeatSuccessKeepsRequestOrder confirms a fully valid batch
298	// renewal still applies every entry and answers in request order.
299	func TestBatchHeartbeatSuccessKeepsRequestOrder(t *testing.T) {
300		router, _ := testRouter(t)
301		registerInstance(t, router, registerBody(at(0)))
302		second := registerBody(at(0))
303		second["instance_id"] = "i-2"
304		registerInstance(t, router, second)
305	
306		body := map[string]any{
307			"service_name": "svc",
308			"instances": []any{
309				map[string]any{"instance_id": "i-2", "heartbeat_at": at(20)},
310				map[string]any{"instance_id": "i-1", "heartbeat_at": -0.25},
311			},
312		}
313		rec := doRequest(t, router, http.MethodPost, "/api/v1/heartbeat", body)
314		if rec.Code != http.StatusOK {
315			t.Fatalf("status = %d body %s", rec.Code, rec.Body.String())
316		}
317		out := decodeBody(t, rec)
318		instances := out["instances"].([]any)
319		if len(instances) != 2 {
320			t.Fatalf("instances len = %d", len(instances))
321		}
322		first := instances[0].(map[string]any)
323		secondEntry := instances[1].(map[string]any)
324		if first["instance_id"] != "i-2" || secondEntry["instance_id"] != "i-1" {
325			t.Fatalf("order not preserved: %v %v", first["instance_id"], secondEntry["instance_id"])
326		}
327		if secondEntry["heartbeat_at"] != "1969-12-31T23:59:59.75Z" {
328			t.Fatalf("i-1 heartbeat_at = %v", secondEntry["heartbeat_at"])
329		}
330	}
331	
332	// TestEvaluateEndpointsRejectInvalidTimes covers discover, batch discover,
333	// cleanup and the service overview: an invalid evaluate_at fails with HTTP
334	// 400 and invalid_parameter and changes no record.
335	func TestEvaluateEndpointsRejectInvalidTimes(t *testing.T) {
336		router, st := testRouter(t)
337		registerInstance(t, router, registerBody(at(0)))
338	
339		invalid := []any{253402300800, -62167219201, "NaN", "-Infinity", "12x34", true, nil}
340		for _, value := range invalid {
341			rec := doRequest(t, router, http.MethodPost, "/api/v1/discover", map[string]any{
342				"service_name": "svc", "evaluate_at": value, "heartbeat_timeout": 1800,
343			})
344			expectErrorShape(t, rec, http.StatusBadRequest, "invalid_parameter")
345	
346			rec = doRequest(t, router, http.MethodPost, "/api/v1/discover/batch", map[string]any{
347				"service_names": []any{"svc"}, "evaluate_at": value, "heartbeat_timeout": 1800,
348			})
349			expectErrorShape(t, rec, http.StatusBadRequest, "invalid_parameter")
350	
351			rec = doRequest(t, router, http.MethodPost, "/api/v1/cleanup", map[string]any{
352				"service_name": "svc", "evaluate_at": value, "heartbeat_timeout": 1800,
353			})
354			expectErrorShape(t, rec, http.StatusBadRequest, "invalid_parameter")
355		}
356	
357		rec := doRequest(t, router, http.MethodGet,
358			"/api/v1/services?evaluate_at=253402300800&heartbeat_timeout=1800", nil)
359		expectErrorShape(t, rec, http.StatusBadRequest, "invalid_parameter")
360	
361		got, found, _ := st.GetInstance("svc", "i-1")
362		if !found || !got.HeartbeatAt.Equal(mustParseTime(baseTime)) {
363			t.Fatalf("record changed after rejected evaluations: %+v", got)
364		}
