367	// TestDiscoverSkewGuardAndBoundaryBehaviour keeps the discovery contract:
368	// an evaluation earlier than a stored heartbeat is a 400, an instance
369	// exactly on the heartbeat-plus-timeout boundary stays online, only a
370	// strictly later evaluation cleans it up, and a scoped request never
371	// touches another service. Weight-descending order is preserved.
372	func TestDiscoverSkewGuardAndBoundaryBehaviour(t *testing.T) {
373		router, st := testRouter(t)
374		registerInstance(t, router, registerBody(at(0)))
375		second := registerBody(at(0))
376		second["instance_id"] = "i-2"
377		second["weight"] = 20
