385		// nothing.
386		rec := doRequest(t, router, http.MethodPost, "/api/v1/discover", map[string]any{
387			"service_name": "svc", "evaluate_at": "2026-10-01T11:00:00Z", "heartbeat_timeout": 1800,
388		})
389		expectErrorShape(t, rec, http.StatusBadRequest, "invalid_parameter")
390		if instances, _ := st.ListInstances("svc"); len(instances) != 2 {
391			t.Fatalf("svc records changed after skew rejection: %d", len(instances))
392		}
393	
394		// Exactly on the boundary both instances are still online, heavier
395		// weight first.
396		rec = doRequest(t, router, http.MethodPost, "/api/v1/discover", map[string]any{
397			"service_name": "svc", "evaluate_at": at(30), "heartbeat_timeout": 1800,
398		})
399		if rec.Code != http.StatusOK {
400			t.Fatalf("status = %d body %s", rec.Code, rec.Body.String())
401		}
402		out := decodeBody(t, rec)
403		if ids := instanceIDs(t, out); len(ids) != 2 || ids[0] != "i-2" || ids[1] != "i-1" {
404			t.Fatalf("ids = %v, want [i-2 i-1]", ids)
405		}
406	
407		// Strictly past the boundary both svc records are cleaned up while the
408		// other service keeps its record.
409		rec = doRequest(t, router, http.MethodPost, "/api/v1/discover", map[string]any{
410			"service_name": "svc", "evaluate_at": at(31), "heartbeat_timeout": 1800,
411		})
412		if rec.Code != http.StatusOK {
413			t.Fatalf("status = %d body %s", rec.Code, rec.Body.String())
414		}
415		if ids := instanceIDs(t, decodeBody(t, rec)); len(ids) != 0 {
416			t.Fatalf("ids = %v, want empty", ids)
417		}
418		if instances, _ := st.ListInstances("svc"); len(instances) != 0 {
419			t.Fatalf("svc records remain after cleanup: %d", len(instances))
420		}
421		if _, found, _ := st.GetInstance("other", "i-9"); !found {
422			t.Fatal("other service record touched by scoped discovery")
423		}
424	}
