426	// TestCleanupBoundaryAndScoping covers the standalone cleanup entry: the
427	// boundary instant removes nothing, a strictly later evaluation removes
428	// exactly the lost records of the named service, and an invalid evaluate_at
429	// removes nothing.
430	func TestCleanupBoundaryAndScoping(t *testing.T) {
431		router, st := testRouter(t)
432		registerInstance(t, router, registerBody(at(0)))
